<?php function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function read_geojson_upload($file){if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)return [null,'Pilih file GeoJSON terlebih dahulu.'];$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,['geojson','json'],true))return [null,'File harus berformat .geojson atau .json.'];if(($file['size']??0)>10*1024*1024)return [null,'Ukuran file maksimal 10 MB.'];$j=json_decode(file_get_contents($file['tmp_name']),true);if(!is_array($j)||!isset($j['type']))return [null,'Isi GeoJSON tidak valid.'];$f=$j['type']==='Feature'?[$j]:($j['type']==='FeatureCollection'?($j['features']??[]):[]);$f=array_values(array_filter($f,fn($x)=>is_array($x)&&isset($x['geometry'])&&is_array($x['geometry'])));if(count($f)!==1)return [null,'Untuk tambah/edit, file harus berisi tepat 1 feature. Untuk banyak feature gunakan Import GeoJSON.'];return [$f[0]['geometry'],null];} ?>